#!/usr/bin/env python3
"""Validate repository-level Agent Skill naming and UI metadata."""

from __future__ import annotations

import re
import sys
from pathlib import Path


NAME_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def parse_frontmatter(skill_md: Path) -> dict[str, str]:
    text = skill_md.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        raise ValueError("missing opening YAML frontmatter delimiter")
    try:
        frontmatter, _ = text[4:].split("\n---\n", 1)
    except ValueError as exc:
        raise ValueError("missing closing YAML frontmatter delimiter") from exc

    values: dict[str, str] = {}
    for line in frontmatter.splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            raise ValueError(f"unsupported frontmatter line: {line!r}")
        key, value = line.split(":", 1)
        values[key.strip()] = value.strip()
    return values


def validate_skill(skill_dir: Path) -> list[str]:
    errors: list[str] = []
    skill_md = skill_dir / "SKILL.md"
    openai_yaml = skill_dir / "agents" / "openai.yaml"

    if not skill_md.is_file():
        return [f"{skill_dir}: missing SKILL.md"]

    try:
        frontmatter = parse_frontmatter(skill_md)
    except ValueError as exc:
        return [f"{skill_md}: {exc}"]

    if set(frontmatter) != {"name", "description"}:
        errors.append(
            f"{skill_md}: frontmatter must contain only name and description"
        )

    name = frontmatter.get("name", "")
    if not NAME_RE.fullmatch(name):
        errors.append(f"{skill_md}: invalid Skill name {name!r}")
    if name != skill_dir.name:
        errors.append(
            f"{skill_md}: name {name!r} must match directory {skill_dir.name!r}"
        )
    if not frontmatter.get("description"):
        errors.append(f"{skill_md}: description must not be empty")

    if not openai_yaml.is_file():
        errors.append(f"{openai_yaml}: missing UI metadata")
    elif f"${name}" not in openai_yaml.read_text(encoding="utf-8"):
        errors.append(f"{openai_yaml}: default prompt must invoke ${name}")

    return errors


def main() -> int:
    repo_root = Path(__file__).resolve().parent.parent
    skills_root = repo_root / "skills"
    skill_dirs = sorted(path for path in skills_root.iterdir() if path.is_dir())
    errors: list[str] = []

    for unwanted in skills_root.rglob("*"):
        if unwanted.name == ".DS_Store" or "__pycache__" in unwanted.parts:
            errors.append(f"{unwanted}: generated file must not be committed")

    for skill_dir in skill_dirs:
        errors.extend(validate_skill(skill_dir))

    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    print(f"Validated {len(skill_dirs)} Skill directories.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
